const ParagraphMenuTextColorSwatchMenuItemFactories = TEXT_COLORS.reduce((items, color, index) => {
	const id = `doc.menu.paragraph-t.text-color.${index}`;
	items[id] = {
		order: index,
		menuItemFactory: (accessor) => ({
			id,
			commandId: SetInlineFormatTextColorCommand.id,
			type: MenuItemType.BUTTON,
			icon: TEXT_COLOR_SWATCH_ICONS[index],
			params: { value: color },
			hidden$: getMenuHiddenObservable(accessor, UniverInstanceType.UNIVER_DOC)
		})
	};
	return items;
}, {});
const ParagraphMenuBackgroundColorSwatchMenuItemFactories = BACKGROUND_COLOR_SWATCH_ICONS.reduce((items, icon, index) => {
	const id = `doc.menu.paragraph-t.background-color.${index}`;
	items[id] = {
		order: index,
		menuItemFactory: (accessor) => {
			const themeService = accessor.get(ThemeService);
			const color = getHighlightBackgroundColor(themeService, index);
			return {
				id,
				commandId: SetInlineFormatTextBackgroundColorCommand.id,
				type: MenuItemType.BUTTON,
				icon,
				params: { value: color },
				hidden$: getMenuHiddenObservable(accessor, UniverInstanceType.UNIVER_DOC)
			};
		}
	};
	return items;
}, {});

