const TabShortCut = {
	id: TabCommand.id,
	binding: KeyCode.TAB,
	preconditions: whenDocAndEditorFocused
};
const UpdateDocFieldsShortcut = {
	id: UpdateSelectedDocFieldsCommand.id,
	binding: KeyCode.F9,
	preconditions: whenDocAndEditorFocused
};
const ShiftTabShortCut = {
	id: TabCommand.id,
	binding: KeyCode.TAB | MetaKeys.SHIFT,
	preconditions: whenDocAndEditorFocused,
	staticParameters: { shift: true }
};

